**Gates before launch.** I save the script below as `spe/evals/harness/r04-workflow.js` and commit it locally on its own. `spe/predictions/r04.yaml` and `spe/plans/r04.md` were committed 10 minutes ago, so the gates can start. I assumed three things that the situation does not state. First, the triage agent runs one trial through `node triage/run.js --config <id> --ticket <id> --tickets <dir> --out <dir>`. Second, that runner writes `result.json` and `transcript.jsonl` and prints the result with usage and cost as JSON. Third, the 50 tickets, with their labels removed, are in `triage/eval-tickets/`.

The gates run in this order:

1. **Grader selftest.** `grade.py` must score the oracle (answers.json fed back as results) at 1.0 on category and priority. It must score an empty result and a deliberately wrong one at 0. It must also confirm that answers.json holds 50 tickets. The earlier eval set had 40 tickets. If answers.json has only 40, I halt and ask you, because only you can decide that.
2. **Control.** I regrade round 3's saved outputs with this round's `grade.py`. The numbers must match round 3's measured values in `spe/prediction-log.md`. If they differ, the grader changed. I log that as a failure before launch.
3. **Dry run.** The dry run uses `round: 4, trials: 1, only: ['B:T001', 'C2:T001', 'C2:T017']`. It must return schema-valid trials, a grader row for every trial, a clean leak scan, and judge scores. It must also report the runner's measured cost per trial. That measured cost replaces the `estTrialUsd` default in the launch args.

I launch the full run only after all three gates pass. No round 4 trial has run yet.

```js
export const meta = {
  name: 'spe-triage-eval',
  description: 'SPE eval for the triage agent. Each config runs each ticket for several trials. Labels are graded in code, reply tone is judged blind by Opus, split cells get extra trials, and the run ends with failure analysis and a completeness critic.',
  phases: [
    { title: 'Trials', detail: 'Run each config on each ticket through the triage runner' },
    { title: 'Grade', detail: 'Code grader on labels, then a transcript scan for peeks' },
    { title: 'Judge', detail: 'Opus scores reply tone blind against judge.md' },
    { title: 'Top-up', detail: 'Extra trials for split cells, up to a cap' },
    { title: 'Synthesis', detail: 'Failure analysis and a completeness critic' },
  ],
}

// Launch args for the full run. The dry run adds trials: 1 and only: ['B:T001', 'C2:T001', 'C2:T017'].
// {
//   round: 4,
//   configs: ['B', 'C2'],
//   tickets: <the 50 ticket ids, copied at launch from the ids in spe/evals/tasks/answers.json>,
//   expectedTickets: 50,
//   trials: 5,
//   spendCapUsd: 40,
//   estTrialUsd: <runner cost per trial measured in the dry run>,
//   maxAgents: 800,
//   topUpPerCell: 5,
//   topUpMaxCells: 20,
// }

// ---------- Round and arguments ----------
const ROUND = Number(args.round)
if (!Number.isInteger(ROUND) || ROUND < 1) throw new Error('args.round must be a positive integer')
const RR = `r${String(ROUND).padStart(2, '0')}`

const CONFIGS = args.configs ?? ['B', 'C2']
const TICKETS = args.tickets ?? []
const EXPECTED_TICKETS = args.expectedTickets ?? 50
const TRIALS = args.trials ?? 5
const ONLY = args.only ?? null
const DRY = Boolean(ONLY)
const OUT = args.outDir ?? `runs/triage-${RR}${DRY ? '-dry' : ''}`
const TICKET_DIR = args.ticketDir ?? 'triage/eval-tickets'
const RUNNER = args.runner ?? 'node triage/run.js'
const DRIVER_MODEL = args.driverModel ?? 'opus'
const JUDGE_MODEL = args.judgeModel ?? 'opus'
const ANALYST_MODEL = args.analystModel ?? 'opus'

// ---------- Paid resources and caps ----------
const CAP_USD = args.spendCapUsd ?? 40
const EST_TRIAL_USD = args.estTrialUsd ?? 0.04            // runner cost, measured by the runner
const DRIVER_OVERHEAD_USD = args.driverOverheadUsd ?? 0.02 // driver agent cost, estimated
const EST_JUDGE_PER_REPLY_USD = args.estJudgePerReplyUsd ?? 0.015
const EST_UTILITY_USD = args.estUtilityUsd ?? 0.1
const EST_ANALYST_USD = args.estAnalystUsd ?? 0.5
const MAX_AGENTS = args.maxAgents ?? 800
const TOPUP_PER_CELL = args.topUpPerCell ?? 5
const TOPUP_MAX_CELLS = args.topUpMaxCells ?? 20

const LEAK_PATTERN = 'spe/(evals|predictions|plans)/|answers\\.json|grade\\.py|judge\\.md|prediction-log|failures\\.md'
const LEAK_RE = new RegExp(LEAK_PATTERN)

// ---------- Cells ----------
if (!DRY && TICKETS.length !== EXPECTED_TICKETS) {
  throw new Error(`Expected ${EXPECTED_TICKETS} tickets, got ${TICKETS.length}`)
}
const cells = []
for (const config of CONFIGS) {
  for (const ticket of TICKETS) {
    if (!ONLY || ONLY.includes(`${config}:${ticket}`)) cells.push({ config, ticket })
  }
}
if (cells.length === 0) throw new Error('No cells selected')

// ---------- Budget ledger ----------
const JUDGE_HOLD = cells.length * TRIALS * EST_JUDGE_PER_REPLY_USD
const UTIL_HOLD = 4 * EST_UTILITY_USD
const SYNTH_HOLD = 2 * EST_ANALYST_USD
const LIMIT_BASE_TRIALS = CAP_USD - JUDGE_HOLD - UTIL_HOLD - SYNTH_HOLD
const LIMIT_GRADE_JUDGE = CAP_USD - SYNTH_HOLD
const LIMIT_TOPUP = CAP_USD - SYNTH_HOLD - 2 * EST_UTILITY_USD

let spentUsd = 0
let heldUsd = 0
let agentsUsed = 0
const skips = []

function skip(what, reason) {
  skips.push({ what, reason })
  log(`SKIP ${what}: ${reason}`)
  return false
}
function reserve(usd, what, limit) {
  if (agentsUsed >= MAX_AGENTS) return skip(what, `agent cap of ${MAX_AGENTS} reached`)
  if (spentUsd + heldUsd + usd > limit) return skip(what, `would pass the $${limit.toFixed(2)} limit for this step`)
  heldUsd += usd
  agentsUsed += 1
  return true
}
function settle(held, actual) {
  heldUsd -= held
  spentUsd += Number.isFinite(actual) ? actual : held
}

log(`Round ${ROUND}: ${CONFIGS.join(', ')} on ${cells.length / CONFIGS.length} tickets, ${TRIALS} trials per cell${DRY ? ' (dry run)' : ''}.`)
log(`Spend cap $${CAP_USD}. Base trials may use $${LIMIT_BASE_TRIALS.toFixed(2)}. Judge hold $${JUDGE_HOLD.toFixed(2)}. Agent cap ${MAX_AGENTS}.`)
log('The judge is Opus, which is the same model family as the Sonnet triage agent. No judge from another family is available, so tone scores may share its blind spots.')

// ---------- Schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['status', 'label', 'reply', 'metrics', 'commands'],
  properties: {
    status: { type: 'string', enum: ['completed', 'harness_error', 'rate_limited'] },
    error: { type: 'string' },
    label: {
      type: 'object',
      required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    metrics: {
      type: 'object',
      required: ['runtime_ms', 'tool_calls', 'tool_errors', 'input_tokens', 'output_tokens', 'cost_usd'],
      properties: {
        runtime_ms: { type: 'number' },
        tool_calls: { type: 'integer' },
        tool_errors: { type: 'integer' },
        input_tokens: { type: 'integer' },
        output_tokens: { type: 'integer' },
        cost_usd: { type: 'number' },
      },
    },
    commands: { type: 'array', items: { type: 'string' } },
  },
}

const GRADE_SCHEMA = {
  type: 'object',
  required: ['rows', 'errors'],
  properties: {
    rows: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'valid', 'category_ok', 'priority_ok'],
        properties: {
          trial_id: { type: 'string' },
          valid: { type: 'boolean' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
        },
      },
    },
    errors: { type: 'array', items: { type: 'string' } },
  },
}

const SCAN_SCHEMA = {
  type: 'object',
  required: ['scanned', 'peeks'],
  properties: {
    scanned: { type: 'integer' },
    peeks: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'path', 'evidence'],
        properties: { trial_id: { type: 'string' }, path: { type: 'string' }, evidence: { type: 'string' } },
      },
    },
  },
}

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['blind_id', 'score', 'pass', 'reason'],
        properties: {
          blind_id: { type: 'string' },
          score: { type: 'integer', minimum: 1, maximum: 5 },
          pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
}

const FAILURE_SCHEMA = {
  type: 'object',
  required: ['types', 'config_gap'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'name', 'kind', 'what', 'how_to_spot', 'seen_in', 'fix', 'is_new'],
        properties: {
          id: { type: 'string' },
          name: { type: 'string' },
          kind: { type: 'string', enum: ['agent', 'grader', 'harness', 'task'] },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          seen_in: { type: 'array', items: { type: 'string' } },
          fix: { type: 'string' },
          is_new: { type: 'boolean' },
        },
      },
    },
    config_gap: { type: 'string' },
  },
}

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['verdict', 'gaps'],
  properties: {
    verdict: { type: 'string', enum: ['complete', 'usable_with_gaps', 'not_scorable'] },
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        required: ['gap', 'severity', 'action'],
        properties: {
          gap: { type: 'string' },
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
          action: { type: 'string' },
        },
      },
    },
  },
}

// ---------- Helpers ----------
const trialId = (config, ticket, k) => `${config}/${ticket}/t${k}`
const mean = xs => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null)
const rate = (xs, f) => mean(xs.map(x => (f(x) ? 1 : 0)))

function seededShuffle(items, seedText) {
  let h = 2166136261
  for (const ch of seedText) h = Math.imul(h ^ ch.charCodeAt(0), 16777619) >>> 0
  const a = items.slice()
  for (let i = a.length - 1; i > 0; i--) {
    h = Math.imul(h ^ (h >>> 15), 2246822519) >>> 0
    const j = h % (i + 1)
    const tmp = a[i]
    a[i] = a[j]
    a[j] = tmp
  }
  return a
}

function halt(reason, extra = {}) {
  log(`HALT: ${reason}`)
  return { round: ROUND, status: 'halted', reason, spentUsd, agentsUsed, skips, ...extra }
}

// ---------- One trial ----------
async function runTrial({ config, ticket }, k, tag, limit) {
  const id = trialId(config, ticket, k)
  const base = { id, config, ticket, k, tag }
  const est = EST_TRIAL_USD + DRIVER_OVERHEAD_USD
  if (!reserve(est, `trial ${id}`, limit)) return { ...base, status: 'skipped' }

  const dir = `${OUT}/${config}/${ticket}/t${k}`
  const prompt = [
    'You run one eval trial for the triage agent. Run this one command from the repo root and report what it printed.',
    '',
    `  ${RUNNER} --config ${config} --ticket ${ticket} --tickets ${TICKET_DIR} --out ${dir}`,
    '',
    'Rules:',
    '- Run only that command. If it fails with a rate limit (HTTP 429 or 529), wait 30 seconds and retry once. If it still fails, set status "rate_limited".',
    '- If the runner crashes for any other reason, set status "harness_error" and copy the error text into "error".',
    '- Do not open, read, list, grep, or cat any file. Take the label, reply, and metrics only from the JSON the runner prints.',
    '- Never touch anything under spe/. The paths spe/evals/, spe/predictions/, and spe/plans/ are off limits.',
    '- Copy the label and the reply exactly. Do not edit or improve them.',
    '- List every shell command you ran in "commands".',
  ].join('\n')

  let r
  try {
    r = await agent(prompt, {
      label: `trial ${id}`,
      phase: tag === 'topup' ? 'Top-up' : 'Trials',
      schema: TRIAL_SCHEMA,
      model: DRIVER_MODEL,
    })
  } catch (e) {
    settle(est, est)
    return { ...base, dir, status: 'harness_error', error: String(e) }
  }
  settle(est, (r.metrics?.cost_usd ?? EST_TRIAL_USD) + DRIVER_OVERHEAD_USD)

  const driverPeek = (r.commands ?? []).find(c => LEAK_RE.test(c))
  return {
    ...base,
    dir,
    ...r,
    voided: Boolean(driverPeek),
    voidReason: driverPeek ? `driver ran: ${driverPeek}` : null,
  }
}

// ---------- Grade and scan ----------
async function gradeAndScan(stage) {
  const gradePrompt = [
    'Run the code grader for this eval and return its rows. Do not edit any file.',
    '',
    `  python spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --runs ${OUT} --json`,
    '',
    'Return one row per result.json the grader scored. Use trial_id "<config>/<ticket>/t<k>" taken from the folder path under the runs folder.',
    'Copy the grader values exactly. Do not regrade anything by hand.',
    'If the grader exits non-zero, skips a file, or warns, put each message in "errors".',
  ].join('\n')

  const scanPrompt = [
    'Scan the triage agent transcripts for peeks at answer keys. Do not edit any file.',
    '',
    `  grep -rnE '${LEAK_PATTERN}' ${OUT} --include=transcript.jsonl`,
    '',
    'Report "scanned" as the number of transcript.jsonl files under the runs folder.',
    'For each hit, decide whether the triage agent read, listed, or searched one of those paths through a tool call. A mention inside the ticket text is not a peek.',
    'Return one row per peeking trial, with trial_id "<config>/<ticket>/t<k>" taken from the folder path, the path it touched, and the matching line as evidence.',
  ].join('\n')

  const okG = reserve(EST_UTILITY_USD, `grader ${stage}`, LIMIT_GRADE_JUDGE)
  const okS = okG && reserve(EST_UTILITY_USD, `leak scan ${stage}`, LIMIT_GRADE_JUDGE)
  if (!okG || !okS) {
    if (okG) settle(EST_UTILITY_USD, 0)
    return { error: 'no budget left for the grader or the leak scan' }
  }
  try {
    const [g, s] = await parallel([
      () => agent(gradePrompt, { label: `grade ${stage}`, phase: 'Grade', schema: GRADE_SCHEMA, model: ANALYST_MODEL }),
      () => agent(scanPrompt, { label: `leak scan ${stage}`, phase: 'Grade', schema: SCAN_SCHEMA, model: ANALYST_MODEL }),
    ])
    return { g, s }
  } catch (e) {
    return { error: `grader or scan agent failed: ${String(e)}` }
  } finally {
    settle(EST_UTILITY_USD, EST_UTILITY_USD)
    settle(EST_UTILITY_USD, EST_UTILITY_USD)
  }
}

function applyGrades(trials, { g, s }) {
  const rows = new Map(g.rows.map(r => [r.trial_id, r]))
  const peeks = new Map(s.peeks.map(p => [p.trial_id, p]))
  const missing = []
  let leakedKey = false
  for (const t of trials) {
    if (t.status !== 'completed') continue
    const peek = peeks.get(t.id)
    if (peek) {
      t.voided = true
      t.voidReason = `transcript touched ${peek.path}`
      if (/answers\.json|grade\.py|judge\.md|spe\/predictions\//.test(peek.path)) leakedKey = true
    }
    const row = rows.get(t.id)
    if (!row) missing.push(t.id)
    else t.grade = { ...row, both_ok: row.category_ok && row.priority_ok }
  }
  return { missing, leakedKey, graderErrors: g.errors, scanned: s.scanned }
}

// ---------- Phase: Trials ----------
phase('Trials')
const trials = await parallel(
  cells.flatMap(cell =>
    Array.from({ length: TRIALS }, (_, i) => () => runTrial(cell, i + 1, 'base', LIMIT_BASE_TRIALS)),
  ),
)
const countBy = (xs, status) => xs.filter(t => t.status === status).length
log(`Trials: ${countBy(trials, 'completed')} completed, ${countBy(trials, 'harness_error')} harness errors, ${countBy(trials, 'rate_limited')} rate limited, ${countBy(trials, 'skipped')} skipped. Spent $${spentUsd.toFixed(2)}.`)

// ---------- Phase: Grade ----------
phase('Grade')
const gs = await gradeAndScan('base')
if (gs.error) return halt(gs.error, { trials })
const baseCheck = applyGrades(trials, gs)
if (baseCheck.graderErrors.length || baseCheck.missing.length) {
  return halt('the grader is broken or incomplete', { graderErrors: baseCheck.graderErrors, missing: baseCheck.missing, trials })
}
if (baseCheck.leakedKey) {
  return halt('a trial read an answer key, a grader, or a prediction', { voided: trials.filter(t => t.voided).map(t => ({ id: t.id, why: t.voidReason })) })
}
log(`Grade: ${trials.filter(t => t.grade).length} rows, ${trials.filter(t => t.voided).length} voided, ${baseCheck.scanned} transcripts scanned.`)

// ---------- Phase: Judge ----------
phase('Judge')
const scoredBase = trials.filter(t => t.status === 'completed' && !t.voided && t.grade)
const byTicket = new Map()
for (const t of scoredBase) {
  if (!byTicket.has(t.ticket)) byTicket.set(t.ticket, [])
  byTicket.get(t.ticket).push(t)
}

await parallel(
  [...byTicket.entries()].map(([ticket, group]) => async () => {
    const order = seededShuffle(group, `${RR}:${ticket}`)
    const blind = order.map((t, i) => ({ blindId: `R${i + 1}`, t }))
    const est = group.length * EST_JUDGE_PER_REPLY_USD
    if (!reserve(est, `judge ${ticket}`, LIMIT_GRADE_JUDGE)) return
    const prompt = [
      'You judge the tone of first replies to one support ticket.',
      `Read the rubric at spe/evals/graders/judge.md and the ticket at ${TICKET_DIR}/${ticket}.json. Do not read any other file. Do not edit any file.`,
      'Score every reply below with the rubric. The replies are in random order and carry no config names.',
      'Judge tone only. Do not judge whether the category or the priority is right.',
      'Return one score per reply, using its blind id.',
      '',
      ...blind.map(b => `--- ${b.blindId} ---\n${b.t.reply}`),
    ].join('\n')
    try {
      const j = await agent(prompt, { label: `judge ${ticket}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL })
      const byBlind = new Map(j.scores.map(s => [s.blind_id, s]))
      for (const b of blind) {
        const s = byBlind.get(b.blindId)
        if (s) b.t.tone = { score: s.score, pass: s.pass, reason: s.reason }
      }
    } catch (e) {
      log(`Judge failed on ${ticket}: ${String(e)}`)
    } finally {
      settle(est, est)
    }
  }),
)
const judgedCount = scoredBase.filter(t => t.tone).length
log(`Judge: ${judgedCount} of ${scoredBase.length} replies scored. Judge spend is estimated, not measured.`)

// ---------- Phase: Top-up ----------
phase('Top-up')
const cellStats = cells.map(c => {
  const ts = scoredBase.filter(t => t.config === c.config && t.ticket === c.ticket)
  const passes = ts.filter(t => t.grade.both_ok).length
  return { ...c, n: ts.length, passes }
})
const split = cellStats
  .filter(c => c.n > 0 && c.passes > 0 && c.passes < c.n)
  .sort((a, b) => Math.abs(a.passes / a.n - 0.5) - Math.abs(b.passes / b.n - 0.5))
if (split.length > TOPUP_MAX_CELLS) {
  for (const c of split.slice(TOPUP_MAX_CELLS)) skip(`top-up ${c.config}/${c.ticket}`, `top-up cell cap of ${TOPUP_MAX_CELLS}`)
}
const topCells = split.slice(0, TOPUP_MAX_CELLS)
log(`Top-up: ${split.length} split cells, topping up ${topCells.length} with up to ${TOPUP_PER_CELL} extra trials each.`)

let topups = []
if (topCells.length) {
  topups = await parallel(
    topCells.flatMap(cell =>
      Array.from({ length: TOPUP_PER_CELL }, (_, i) => () => runTrial(cell, TRIALS + i + 1, 'topup', LIMIT_TOPUP)),
    ),
  )
  const tgs = await gradeAndScan('topup')
  if (tgs.error) return halt(tgs.error, { trials, topups })
  const topCheck = applyGrades(topups, tgs)
  if (topCheck.graderErrors.length || topCheck.missing.length) {
    return halt('the grader is broken or incomplete on top-up trials', { graderErrors: topCheck.graderErrors, missing: topCheck.missing })
  }
  if (topCheck.leakedKey) return halt('a top-up trial read an answer key, a grader, or a prediction')
}

// ---------- Summaries ----------
const allTrials = trials.concat(topups)
function summarize(config) {
  const base = trials.filter(t => t.config === config)
  const scored = base.filter(t => t.status === 'completed' && !t.voided && t.grade)
  const judged = scored.filter(t => t.tone)
  const cellMeansWithTopup = cells
    .filter(c => c.config === config)
    .map(c => allTrials.filter(t => t.config === config && t.ticket === c.ticket && t.status === 'completed' && !t.voided && t.grade))
    .filter(ts => ts.length)
    .map(ts => rate(ts, t => t.grade.both_ok))
  return {
    config,
    planned: cells.filter(c => c.config === config).length * TRIALS,
    completed: countBy(base, 'completed'),
    harness_error: countBy(base, 'harness_error'),
    rate_limited: countBy(base, 'rate_limited'),
    skipped: countBy(base, 'skipped'),
    voided: base.filter(t => t.voided).length,
    scored: scored.length,
    valid_label_rate: rate(scored, t => t.grade.valid),
    category_acc: rate(scored, t => t.grade.category_ok),
    priority_acc: rate(scored, t => t.grade.priority_ok),
    both_acc: rate(scored, t => t.grade.both_ok),
    both_acc_cell_mean_with_topup: mean(cellMeansWithTopup),
    tone_pass_rate: rate(judged, t => t.tone.pass),
    tone_mean: mean(judged.map(t => t.tone.score)),
    judge_coverage: scored.length ? judged.length / scored.length : null,
    runtime_ms_mean: mean(scored.map(t => t.metrics.runtime_ms)),
    tool_calls_mean: mean(scored.map(t => t.metrics.tool_calls)),
    tool_errors_mean: mean(scored.map(t => t.metrics.tool_errors)),
    tokens_mean: mean(scored.map(t => t.metrics.input_tokens + t.metrics.output_tokens)),
    cost_usd_mean: mean(scored.map(t => t.metrics.cost_usd)),
  }
}
const summary = CONFIGS.map(summarize)
const CEILING_METRICS = ['category_acc', 'priority_acc', 'both_acc', 'tone_pass_rate']
const ceilings = CEILING_METRICS.filter(m => summary.every(s => s[m] === 1))
if (ceilings.length) log(`Ceiling: every config scored 1.0 on ${ceilings.join(', ')}. Those predictions are not scorable.`)
for (const s of summary) {
  log(`${s.config}: both ${s.both_acc?.toFixed(3)}, category ${s.category_acc?.toFixed(3)}, priority ${s.priority_acc?.toFixed(3)}, tone pass ${s.tone_pass_rate?.toFixed(3)}, n=${s.scored}`)
}

// ---------- Phase: Synthesis ----------
phase('Synthesis')
const failing = allTrials
  .filter(t => t.status === 'completed' && !t.voided && t.grade && (!t.grade.both_ok || (t.tone && !t.tone.pass)))
  .slice(0, 150)
  .map(t => ({
    id: t.id,
    dir: t.dir,
    tag: t.tag,
    label: t.label,
    category_ok: t.grade.category_ok,
    priority_ok: t.grade.priority_ok,
    tone: t.tone ?? null,
  }))

let failures = null
if (reserve(EST_ANALYST_USD, 'failure analysis', CAP_USD)) {
  try {
    failures = await agent(
      [
        `You do failure analysis for an eval of the triage agent, configs ${CONFIGS.join(' and ')}.`,
        'Below are the per-config numbers and the trials that failed a label check or the tone judge. Each trial folder holds result.json and transcript.jsonl.',
